    56	public enum SaleStatus {
    57	    PENDING_SHIPMENT,    // 판매자 발송 대기
    58	    IN_TRANSIT,          // 배송 중
    59	    IN_INSPECTION,       // 검수 중
    60	    FAILED_INSPECTION,   // 검수 불합격
    61	    IN_STORAGE,          // 창고 보관 중
    62	    ON_AUCTION,          // 판매 입찰 중
    63	    SELLING,             // 판매중 (등록된 상태)
    64	    SOLD,                // 판매 완료
    65	    AUCTION_EXPIRED;     // 입찰 기한 만료
    66	
    67	    // 상태 전환 규칙
    68	    public boolean canTransitionTo(SaleStatus newStatus) {
    69	        return switch (this) {
    70	            case PENDING_SHIPMENT -> newStatus == IN_TRANSIT;
    71	            case IN_TRANSIT -> newStatus == IN_INSPECTION;
    72	            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
    73	            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
    74	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
    75	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
    76	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false; // SOLD 상태에서는 다른 상태로 전환 불가
    77	        };
    78	    }
